import java.io.BufferedReader;import java.io.InputStreamReader;import java.util.StringTokenizer;public class TestClass {public static void main(String[] args) throws Exception {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));String line = br.readLine();if (line == null) return;int t = Integer.parseInt(line.trim());while (t-- > 0) {int n = Integer.parseInt(br.readLine().trim());StringTokenizer st = new StringTokenizer(br.readLine());int count0 = 0;int count1 = 0;for (int i = 0; i < n; i++) {int val = Integer.parseInt(st.nextToken());if (val % 2 == 0) {count0++;} else {count1++;}}int oddCount = 0;if (count0 % 2 != 0) oddCount++;if (count1 % 2 != 0) oddCount++;if (oddCount <= 1) {System.out.println(1);} else {System.out.println(0);}}}}